// ❌ BAD: Storing state in local RAM
// This fails the moment you add a second server.
static Dictionary<string, UserSession> _activeUsers = new();

// ✅ GOOD: Storing state in a distributed cache
// All 500 servers can read this exact same data instantly.
await _redisCache.SetStringAsync("session_123", userData);

# ⚙️ NGINX LOAD BALANCER CONFIG

upstream backend {
    # ❌ ANTI-PATTERN: Sticky Sessions via IP Hashing
    # Bob's IP will mathematically always route to the same server.
    ip_hash; 

    server 10.0.0.1;
    server 10.0.0.2;
    server 10.0.0.3;
}
